        assert(gks_ion->lower_bc[dir].type != GKYL_BC_GK_SPECIES_ZERO_FLUX);
        assert(gks_ion->lower_bc[dir].type != GKYL_BC_GK_SPECIES_REFLECT);
      } else {
        assert(gks_ion->upper_bc[dir].type != GKYL_BC_GK_SPECIES_ZERO_FLUX);
        assert(gks_ion->upper_bc[dir].type != GKYL_BC_GK_SPECIES_REFLECT);
      }

      // Default scenario: we set the ranges to the full range of the ghost cells.
      sca->boundaries_conf_ghost[j] = edge == GKYL_LOWER_EDGE ? app->local_lower_ghost[dir] :
                                                                app->local_upper_ghost[dir];
      sca->boundaries_dir[j] = dir;
      sca->boundaries_edge[j] = edge;

      // Specific scenario if we are in a inner wall limited case. We select only SOL range in parallel direction.
    sca->dndt_react = mkarr(app->use_gpu, gkns->basis.num_basis, gkns->local_ext.volume);
  }
}

void
gk_neut_species_scaling_apply_ic_cross(
  struct gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_scaling *sca
)
{
  if (sca->type == GKYL_GK_SPECIES_SCALING_RECYCLING_IZ_BALANCE) {
    // Project and store the initial state. Need to re-project so that restarts use this as the state at t=0.
    if (gkns->info.init_from_file.type == 0) {
      gk_neut_species_projection_calc(app, gkns, &gkns->proj_init, gkns->f1, 0.0);
    }

    gkyl_array_set_offset(sca->Jm0_init, 1.0 / gkns->info.mass, gkns->f1, 0);

    if (gkns->info.init_from_file.type == 0) {
      gkyl_array_clear(gkns->f1, 0.0);
    }
  }
}

void
gk_neut_species_scaling_cross_moms(
  gkyl_gyrokinetic_app *app, const struct gk_neut_species *gkns, struct gk_scaling *sca,
  const struct gkyl_array *fin[], const struct gkyl_array *fin_neut[]
)
{
  sca->cross_moms_func_neut(app, gkns, sca, fin, fin_neut);
}

void
gk_neut_species_scaling_rhs(
  gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_scaling *sca,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  sca->rhs_func_neut(app, gkns, sca, fin, rhs);
}

void
gk_neut_species_scaling_apply(
  gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_scaling *sca,
  struct gkyl_array *fin, struct gkyl_array **bflux[]
)
{
  sca->apply_func_neut(app, gkns, sca, fin, bflux);
}

void
gk_neut_species_scaling_write(
  gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_scaling *sca, int ridx,
  double tm, int frame
)
{
  sca->write_func_neut(app, gkns, sca, ridx, tm, frame);
}

void
gk_neut_species_scaling_release(const struct gkyl_gyrokinetic_app *app, const struct gk_scaling *sca)
{
  if (sca->type == GKYL_GK_SPECIES_SCALING_RECYCLING_IZ_BALANCE) {
    gkyl_array_release(sca->Jm0_init);
    gkyl_array_integrate_release(sca->integrate_op);

    if (app->use_gpu) {
      gkyl_cu_free(sca->react_vol_integ_local);
      gkyl_cu_free(sca->react_vol_integ_global);
      gkyl_cu_free(sca->bflux_m0_vol_integ_local);
    } else {
      gkyl_free(sca->react_vol_integ_local);
      gkyl_free(sca->react_vol_integ_global);
      gkyl_free(sca->bflux_m0_vol_integ_local);
    }
    gkyl_array_release(sca->reactivity);
    gkyl_array_release(sca->dndt_react);

    gkyl_dg_iz_release(sca->iz_react_calc);
  }
}
