   545	    // f_react = n_donor*(fmax1(n_elc, upar_elc, vtiz1^2) + fmax2(n_elc, upar_donor, vtiz2^2) - f_elc)
   546	    // RHS update is then obtained by incrementing rhs += coeff_react*f_react
   547	    react->f_react = mkarr(app->use_gpu, gks->basis.num_basis, gks->local_ext.volume);
   548	
   549	    for (int i = 0; i < react->num_react; ++i) {
   550	      react->react_id[i] = react->react_type[i].react_id;
   551	      react->type_self[i] = react->react_type[i].type_self;
   552	
