   554	      react->species_elc[i] = gk_find_species(app, react->react_type[i].elc_nm);
   555	      react->species_ion[i] = gk_find_species(app, react->react_type[i].ion_nm);
   556	      if (react->species_elc[i]->is_fluid || react->species_ion[i]->is_fluid) {
   557	        gkyl_exit("Reactions with charged fluid species are not supported.");
   558	      }
   559	
   560	      // Fetch index of species for indexing arrays
   561	      react->elc_idx[i] = gk_find_species_idx(app, react->react_type[i].elc_nm);
   562	      react->ion_idx[i] = gk_find_species_idx(app, react->react_type[i].ion_nm);
