   410	    // react->f_react = n_elc*coeff_react*fmax(n_ion, upar_ion b_i, vt_ion^2)
   411	    react->f_react = mkarr(app->use_gpu, gkns->basis.num_basis, gkns->local_ext.volume);
   412	
   413	    for (int i = 0; i < react->num_react; ++i) {
   414	      react->react_id[i] = react->react_type[i].react_id;
   415	      react->type_self[i] = react->react_type[i].type_self;
   416	      // Fetch pointers to species objects
   417	      react->species_elc[i] = gk_find_species(app, react->react_type[i].elc_nm);
   418	      react->species_ion[i] = gk_find_species(app, react->react_type[i].ion_nm);
   419	      if (react->species_elc[i]->is_fluid || react->species_ion[i]->is_fluid) {
   420	        gkyl_exit("Reactions with charged fluid species are not supported.");
   421	      }
