   423	      react->elc_idx[i] = gk_find_species_idx(app, react->react_type[i].elc_nm);
   424	      react->ion_idx[i] = gk_find_species_idx(app, react->react_type[i].ion_nm);
   425	
   426	      // Compute a minimum representable temperature based on the smallest dv in the grid.
   427	      double ion_vt_sq_min = gk_species_react_get_vt_sq_min(app, &app->species[react->ion_idx[i]]);
   428	      double neut_vt_sq_min;
   429	      if (gk_find_neut_species(app, react->react_type[i].donor_nm)) {
   430	        react->donor_idx[i] = gk_find_neut_species_idx(app, react->react_type[i].donor_nm);
   431	      } else if (gk_find_neut_species(app, react->react_type[i].partner_nm)) {
   432	        react->partner_idx[i] = gk_find_neut_species_idx(app, react->react_type[i].partner_nm);
   433	        neut_vt_sq_min =
