   440	      react->react_lte_moms[i] =
   441	        mkarr(app->use_gpu, 5 * app->basis.num_basis, app->local_ext.volume);
   442	
   443	      react->vt_sq_iz1[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
   444	      react->vt_sq_iz2[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
   445	
   446	      react->u_i_dot_b_i[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
   447	
   448	      // J*n for use in final update formulae of reactions
   449	      react->Jm0_elc[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
   450	      react->Jm0_partner[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
