   453	      react->upar_ion[i] = mkarr(app->use_gpu, 3 * app->basis.num_basis, app->local_ext.volume);
   454	      react->vt_sq_ion[i] = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
   455	
   456	      if (react->react_id[i] == GKYL_REACT_IZ) {
   457	        struct gkyl_dg_iz_inp iz_inp = {
   458	          .cbasis = &app->basis,
   459	          .conf_rng = &app->local,
   460	          .type_ion = react->react_type[i].ion_id,
   461	          .charge_state = react->react_type[i].charge_state,
   462	          .type_self = react->type_self[i],
   463	        };
   464	        react->iz[i] = gkyl_dg_iz_new(&iz_inp, app->use_gpu);
   465	      } else if (react->react_id[i] == GKYL_REACT_RECOMB) {
   466	        struct gkyl_dg_recomb_inp recomb_inp = {
   467	          .grid = &gkns->grid,
